def test_messenger_parse_text_event() -> None:
    adapter = MessengerAdapter(verify_token="verify", page_access_token="page-token", app_secret="")
    payload = {
        "entry": [
            {
                "messaging": [
                    {
                        "sender": {"id": "user-1"},
                        "message": {"text": "hello"},
                    }
                ]
            }
        ]
    }

    messages = adapter.parse_events(payload)

