async def index_document_task(document_id: int, path: str) -> None:
    from chatbot_manager.db import get_engine

    with Session(get_engine()) as session:
        document = session.get(KnowledgeDocument, document_id)
        if document is None:
            return
        try:
            settings = assistant_settings(session)
            await rag_service_from_assistant(settings).index_document(Path(path))
            document.status = "indexed"
            document.error = ""
            document.indexed_at = utc_now()
        except Exception as exc:
            document.status = "failed"
            document.error = str(exc)
        document.updated_at = utc_now()
        session.add(document)
        session.commit()


