<script>
  const knowledgeTableBody = document.querySelector("#knowledge-table tbody");
  const knowledgeStatus = document.getElementById("knowledge-status");

  function renderKnowledgeDocuments(documents) {
    knowledgeTableBody.innerHTML = documents.map((document) => `
      <tr data-document-id="${document.id}">
        <td>${escapeHtml(document.filename)}</td>
        <td data-field="status">${escapeHtml(document.status)}</td>
        <td data-field="indexed_at">${escapeHtml(document.indexed_at || "")}</td>
        <td data-field="error">${escapeHtml(document.error || "")}</td>
