  function escapeHtml(value) {
    return String(value)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

  async function refreshKnowledgeDocuments() {
    try {
      const response = await fetch("/api/knowledge-documents");
      const payload = await response.json();
