    } catch (error) {
      knowledgeStatus.textContent = error.message;
    }
  }

  const hasPendingDocuments = Array.from(document.querySelectorAll('[data-field="status"]'))
    .some((cell) => cell.textContent.trim() === "pending");
  const knowledgePoller = window.setInterval(refreshKnowledgeDocuments, 3000);
  if (!hasPendingDocuments) window.clearInterval(knowledgePoller);
