  const detailMeta = document.getElementById("graph-detail-meta");
  const detailProperties = document.getElementById("graph-detail-properties");
  const labelSelect = document.getElementById("entity-label-select");

  function clearGraph() {
    while (canvas.firstChild) {
      canvas.removeChild(canvas.firstChild);
    }
  }

  function setDetail(node) {
    detailTitle.textContent = node.label || node.id;
    detailMeta.textContent = node.id;
    detailProperties.textContent = JSON.stringify(node.properties || {}, null, 2);
