  function drawGraph(graph) {
    clearGraph();
    const nodes = graph.nodes || [];
    const edges = graph.edges || [];
    empty.hidden = nodes.length > 0;
    if (!nodes.length) {
      status.textContent = "No graph nodes found for this label.";
      return;
    }

    const width = canvas.clientWidth || 900;
    const height = canvas.clientHeight || 560;
    canvas.setAttribute("viewBox", `0 0 ${width} ${height}`);
    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.max(120, Math.min(width, height) * 0.34);
    const positions = new Map();

    nodes.forEach((node, index) => {
      const angle = nodes.length === 1 ? -Math.PI / 2 : (Math.PI * 2 * index) / nodes.length - Math.PI / 2;
      positions.set(node.id, {
        x: nodes.length === 1 ? centerX : centerX + Math.cos(angle) * radius,
        y: nodes.length === 1 ? centerY : centerY + Math.sin(angle) * radius,
      });
    });

