    canvas.appendChild(defs);

    edges.forEach((edge) => {
      const source = positions.get(edge.source);
      const target = positions.get(edge.target);
      if (!source || !target) return;
      const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
      line.setAttribute("x1", source.x);
      line.setAttribute("y1", source.y);
      line.setAttribute("x2", target.x);
      line.setAttribute("y2", target.y);
      line.setAttribute("class", "graph-edge");
      line.setAttribute("marker-end", "url(#arrow)");
      canvas.appendChild(line);

      if (edge.type) {
        const label = document.createElementNS("http://www.w3.org/2000/svg", "text");
        label.setAttribute("x", (source.x + target.x) / 2);
        label.setAttribute("y", (source.y + target.y) / 2);
        label.setAttribute("class", "graph-edge-label");
        label.textContent = edge.type;
        canvas.appendChild(label);
      }
    });

    nodes.forEach((node) => {
      const position = positions.get(node.id);
      const group = document.createElementNS("http://www.w3.org/2000/svg", "g");
      group.setAttribute("class", "graph-node");
      group.setAttribute("tabindex", "0");
      group.setAttribute("transform", `translate(${position.x} ${position.y})`);
      group.addEventListener("click", () => setDetail(node));
      group.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") setDetail(node);
      });

      const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
      circle.setAttribute("r", "38");
      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("text-anchor", "middle");
      text.setAttribute("dy", "5");
      text.textContent = node.label || node.id;
      group.appendChild(circle);
      group.appendChild(text);
      canvas.appendChild(group);
    });

    setDetail(nodes[0]);
    status.textContent = graph.is_truncated ? "Graph truncated. Lower depth or max nodes for a tighter view." : `${nodes.length} nodes, ${edges.length} relationships.`;
